44: /**
45:  * People text in clusters. Inside a burst the gap is short; once the burst is
46:  * spent she goes quiet for a long stretch, which is what keeps eight a day from
47:  * reading as a metronome.
48:  */
49: export function burstGate(db: DatabaseSync, ownerId: string): GateResult {
50:   const recent = db
51:     .prepare(
52:       `SELECT sent_at FROM mem_initiative_log
53:        WHERE owner_id = ? AND sent_at >= datetime('now', ?)
54:        ORDER BY sent_at DESC`,
55:     )
56:     .all(ownerId, `-${env.proactiveBurstWindowMinutes} minutes`) as Array<{
57:     sent_at: string;
58:   }>;
59: 
60:   const lastGapMin = hoursSince(getLastInitiativeAt(db, ownerId)) * 60;
61:   // Into silence: one bubble at a time. Engaged (unanswered=0): keep burst max.
62:   const unanswered = unansweredCount(db, ownerId);
63:   const burstMax = unanswered >= 1 ? 1 : env.proactiveBurstMax;
64: 
65:   if (recent.length >= burstMax) {
66:     const restMin = env.proactiveBurstRestMinutes;
67:     if (lastGapMin < restMin) {
68:       return deny("burst_spent", Math.ceil((restMin - lastGapMin) * 60));
69:     }
70:     return ok;
71:   }
72: 
73:   if (lastGapMin < env.proactiveBurstGapMinutes) {
74:     return deny(
75:       "burst_gap",
76:       Math.ceil((env.proactiveBurstGapMinutes - lastGapMin) * 60),
77:     );
78:   }
