91:   now = new Date(),
92: ): GateResult {
93:   if (!options.enabled) return deny("proactive_disabled");
94:   if (options.busy) return deny("chat_in_progress", 60);
95:   if (inOwnTime(db, ownerId, now)) return deny("own_time");
