107:   if (unanswered >= env.proactiveMaxUnanswered) {
108:     if (sinceLastInitH < capBackoffH) {
109:       return deny(
110:         "nudge_cap_backoff",
111:         Math.ceil((capBackoffH - sinceLastInitH) * 3600),
112:       );
113:     }
114:     // 6h rest elapsed — allow one more attempt into silence.
115:   } else if (unanswered >= 1) {
116:     if (sinceLastInitH < nudgeTimeoutH) {
117:       return deny(
118:         "nudge_timeout",
119:         Math.ceil((nudgeTimeoutH - sinceLastInitH) * 3600),
120:       );
121:     }
122:   }
123: 
124:   const idleH = hoursSince(getLastUserMessageAt(db, ownerId));
125: 
126:   // A nudge belongs to a live session: he is around, and she dropped the ball
127:   // inside it. Cold outreach is the opposite case and keeps the idle floor.
128:   if (options.nudge) {
129:     if (idleH > env.proactiveSessionWindowHours) return deny("no_live_session");
130:     return burstGate(db, ownerId);
131:   }
132: 
133:   if (idleH < env.proactiveMinIdleHours) {
134:     return deny(
135:       "user_active_recently",
136:       Math.ceil((env.proactiveMinIdleHours - idleH) * 3600),
137:     );
138:   }
139: 
140:   return burstGate(db, ownerId);
141: }
