376: export function pickCandidate(
377:   db: DatabaseSync,
378:   ownerId: string,
379:   context: { idleHours: number },
380: ): Candidate | null {
381:   const ripe = collectCandidates(db, ownerId, context).filter(
382:     (c) => c.score >= env.proactiveMinScore,
383:   );
384:   if (ripe.length === 0) return null;
385: 
386:   const hasAgenda = ripe.some(
387:     (c) =>
388:       c.kind !== "check_in" &&
389:       (c.lane === "A" ||
390:         c.lane === "B" ||
391:         c.kind === "she_owes" ||
392:         c.kind === "he_never_answered" ||
393:         c.kind === "time_anchored" ||
394:         c.kind === "callback" ||
395:         c.kind === "stance" ||
396:         (c.kind === "curiosity_take" && c.lane !== "C") ||
397:         c.kind === "watch_fired"),
398:   );
399: 
400:   // Presence only when nothing sharper is ripe.
401:   let pool = ripe;
402:   if (hasAgenda) {
403:     pool = ripe.filter((c) => c.kind !== "check_in");
404:   }
405: 
406:   const hasAB = pool.some((c) => c.lane === "A" || c.lane === "B");
407:   if (hasAB) {
408:     pool = pool.filter((c) => c.lane !== "C");
409:   }
410: 
411:   // A > B > C among curiosity; otherwise best score.
412:   const laneRank = (c: Candidate): number => {
413:     if (c.lane === "A") return 3;
414:     if (c.lane === "B") return 2;
415:     if (c.lane === "C") return 1;
416:     return 0;
417:   };
418:   pool.sort(
419:     (a, b) => laneRank(b) - laneRank(a) || b.score - a.score,
420:   );
421:   return pool[0] ?? null;
422: }
